import request from 'supertest';
import express from 'express';
import mongoose from 'mongoose';
import jwt from 'jsonwebtoken';
import { patientRoutes } from '../routes/patients';
import { Patient } from '../models/patient';
import { User } from '../models/user';

const app = express();
app.use(express.json());
app.use('/patients', patientRoutes);

describe('Patient Routes', () => {
  let adminToken: string;
  let doctorToken: string;
  let patientToken: string;
  let testPatientId: string;

  beforeAll(async () => {
    // Connect to test database
    await mongoose.connect(process.env.MONGODB_TEST_URI || 'mongodb://localhost:27017/healthcare-test');

    // Create test users
    const admin = await User.create({
      email: 'admin@test.com',
      password: 'password123',
      userType: 'admin'
    });

    const doctor = await User.create({
      email: 'doctor@test.com',
      password: 'password123',
      userType: 'doctor'
    });

    const patient = await User.create({
      email: 'patient@test.com',
      password: 'password123',
      userType: 'patient'
    });

    // Generate tokens
    adminToken = jwt.sign(
      { id: admin._id, userType: 'admin' },
      process.env.JWT_SECRET || 'test-secret',
      { expiresIn: '1h' }
    );

    doctorToken = jwt.sign(
      { id: doctor._id, userType: 'doctor' },
      process.env.JWT_SECRET || 'test-secret',
      { expiresIn: '1h' }
    );

    patientToken = jwt.sign(
      { id: patient._id, userType: 'patient' },
      process.env.JWT_SECRET || 'test-secret',
      { expiresIn: '1h' }
    );

    // Create a test patient
    const testPatient = await Patient.create({
      firstName: 'Test',
      lastName: 'Patient',
      dateOfBirth: new Date('1990-01-01'),
      gender: 'male',
      contactNumber: '1234567890',
      email: 'test@patient.com',
      address: '123 Test St',
      medicalHistory: 'No significant history',
      assignedDoctor: doctor._id
    });

    testPatientId = testPatient._id.toString();
  });

  afterAll(async () => {
    // Clean up test data
    await User.deleteMany({});
    await Patient.deleteMany({});
    await mongoose.connection.close();
  });

  describe('GET /patients', () => {
    it('should allow admin to get all patients', async () => {
      const response = await request(app)
        .get('/patients')
        .set('Authorization', `Bearer ${adminToken}`);

      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });

    it('should not allow non-admin users to get all patients', async () => {
      const response = await request(app)
        .get('/patients')
        .set('Authorization', `Bearer ${doctorToken}`);

      expect(response.status).toBe(403);
    });
  });

  describe('GET /patients/:id', () => {
    it('should allow admin to get any patient', async () => {
      const response = await request(app)
        .get(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${adminToken}`);

      expect(response.status).toBe(200);
      expect(response.body._id).toBe(testPatientId);
    });

    it('should allow doctor to get their assigned patient', async () => {
      const response = await request(app)
        .get(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${doctorToken}`);

      expect(response.status).toBe(200);
      expect(response.body._id).toBe(testPatientId);
    });

    it('should not allow unauthorized access', async () => {
      const response = await request(app)
        .get(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${patientToken}`);

      expect(response.status).toBe(403);
    });
  });

  describe('POST /patients', () => {
    it('should allow admin to create a new patient', async () => {
      const newPatient = {
        firstName: 'New',
        lastName: 'Patient',
        dateOfBirth: new Date('1995-01-01'),
        gender: 'female',
        contactNumber: '9876543210',
        email: 'new@patient.com',
        address: '456 New St',
        medicalHistory: 'No history'
      };

      const response = await request(app)
        .post('/patients')
        .set('Authorization', `Bearer ${adminToken}`)
        .send(newPatient);

      expect(response.status).toBe(201);
      expect(response.body.firstName).toBe(newPatient.firstName);
    });

    it('should not allow non-admin users to create patients', async () => {
      const response = await request(app)
        .post('/patients')
        .set('Authorization', `Bearer ${doctorToken}`)
        .send({});

      expect(response.status).toBe(403);
    });
  });

  describe('PUT /patients/:id', () => {
    it('should allow admin to update any patient', async () => {
      const update = {
        firstName: 'Updated',
        lastName: 'Patient'
      };

      const response = await request(app)
        .put(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send(update);

      expect(response.status).toBe(200);
      expect(response.body.firstName).toBe(update.firstName);
    });

    it('should allow doctor to update their assigned patient', async () => {
      const update = {
        medicalHistory: 'Updated history'
      };

      const response = await request(app)
        .put(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${doctorToken}`)
        .send(update);

      expect(response.status).toBe(200);
      expect(response.body.medicalHistory).toBe(update.medicalHistory);
    });
  });

  describe('DELETE /patients/:id', () => {
    it('should allow admin to delete a patient', async () => {
      const response = await request(app)
        .delete(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${adminToken}`);

      expect(response.status).toBe(200);
    });

    it('should not allow non-admin users to delete patients', async () => {
      const response = await request(app)
        .delete(`/patients/${testPatientId}`)
        .set('Authorization', `Bearer ${doctorToken}`);

      expect(response.status).toBe(403);
    });
  });
}); 